// ============================================================
// CONFIG - único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  diasRadar: 20,                 // entra no radar com X dias ou mais sem comprar
  diasMaximoRadar: 40,           // sai do radar com mais de X dias (0 = sem limite)
  qtdComprasNovo: 1,             // cliente novo = exatamente X compras em todo o histórico
  nomesIgnorados: ["CONSUMIDOR FINAL"],
  nomeSemVendedor: "SEM VENDEDOR",
  nomeAba: "Página1",            // nome da primeira aba das planilhas novas (conta Google em português)
  aliases: {                     // nomes aceitos das colunas do relatório (sem acento, sem símbolos, minúsculas)
    codigo: ["codigo", "codcliente", "codigocliente"],
    cliente: ["nome", "nomcliente", "nomecliente", "cliente", "razaosocial"],
    qtd: ["qtdcompras", "qtdvendas", "quantidadecompras", "quantidadevendas", "totalcompras", "numcompras", "qtde"],
    ultimaCompra: ["dtultimacompra", "dataultimacompra", "ultimacompra", "dtultcompra"],
    fone: ["fone", "telefone"],
    celular: ["celular", "whatsapp"],
    email: ["email", "emailcliente"],
    vendedorCodigo: ["vendedorcodigo", "codvendedor", "codigovendedor"],
    vendedor: ["vendedor", "nomvendedor", "nomevendedor", "representante"]
  }
};

function pegarRegistros(nodeJson) {
  if (!nodeJson) return [];
  if (!nodeJson.dados) return [];
  if (!Array.isArray(nodeJson.dados) || nodeJson.dados.length === 0) return [];
  const bloco = nodeJson.dados[0];
  if (!bloco || !Array.isArray(bloco.dados)) return [];
  return bloco.dados;
}

const cacheChave = {};
function normalizarChave(texto) {
  const bruto = String(texto);
  if (cacheChave[bruto] !== undefined) return cacheChave[bruto];
  const r = bruto.toLowerCase()
    .replace(/[àáâãä]/g, "a").replace(/[èéêë]/g, "e").replace(/[ìíîï]/g, "i")
    .replace(/[òóôõö]/g, "o").replace(/[ùúûü]/g, "u").replace(/ç/g, "c")
    .replace(/[^a-z0-9]/g, "");
  cacheChave[bruto] = r;
  return r;
}

// Descobre uma vez, por conjunto de colunas, qual coluna real corresponde a cada campo
const cacheColunas = {};
function colunasDe(registro) {
  const chaves = Object.keys(registro);
  const assinatura = chaves.join("|");
  if (cacheColunas[assinatura]) return cacheColunas[assinatura];
  const mapa = {};
  chaves.forEach(function (k) { mapa[normalizarChave(k)] = k; });
  const resolvido = {};
  Object.keys(CONFIG.aliases).forEach(function (campo) {
    resolvido[campo] = null;
    const lista = CONFIG.aliases[campo];
    for (let i = 0; i < lista.length; i++) {
      if (mapa[lista[i]] !== undefined) { resolvido[campo] = mapa[lista[i]]; break; }
    }
  });
  console.log("Colunas do relatório: " + chaves.join(", ") + " | usadas: " + JSON.stringify(resolvido));
  cacheColunas[assinatura] = resolvido;
  return resolvido;
}

function pegarCampo(registro, campo) {
  const col = colunasDe(registro)[campo];
  if (col === null || col === undefined) return "";
  const v = registro[col];
  return (v === undefined || v === null) ? "" : v;
}

function decodificarEntidadesHtml(texto) {
  if (texto === null || texto === undefined) return "";
  const t = String(texto);
  if (t.indexOf("&") < 0) return t;
  return t.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"").replace(/&#39;/g, "'").replace(/&apos;/g, "'");
}

function escaparHtml(texto) {
  if (texto === null || texto === undefined) return "";
  return String(texto).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}

// Retorna dias desde 1970 (UTC) ou null. Aceita AAAA-MM-DD (com ou sem hora) e DD/MM/AAAA. 1900-01-01 = nulo do ERP.
function diaDaData(valor) {
  if (!valor) return null;
  const texto = String(valor).trim();
  let a, m, d;
  let r = texto.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (r) { a = Number(r[1]); m = Number(r[2]); d = Number(r[3]); }
  else {
    r = texto.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
    if (!r) return null;
    d = Number(r[1]); m = Number(r[2]); a = Number(r[3]);
  }
  if (a <= 1900) return null;
  return Math.floor(Date.UTC(a, m - 1, d) / 86400000);
}

function formatarDataBr(valor) {
  const r = String(valor).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (r) return r[3] + "/" + r[2] + "/" + r[1];
  return String(valor).substring(0, 10);
}

// Compara códigos sem diferenciar "12", " 12 " e "12.0"
function chaveCodigo(valor) {
  if (valor === null || valor === undefined) return "";
  const texto = String(valor).trim();
  if (texto === "") return "";
  if (/^-?\d+(\.\d+)?$/.test(texto)) {
    const numero = Number(texto);
    if (!isNaN(numero)) return String(numero);
  }
  return texto.toUpperCase();
}

// Telefone válido para WhatsApp: 55 + DDD (1 a 9) + 8 dígitos (fixo) ou 9 dígitos começando com 9 (celular)
function normalizarTelefone(bruto) {
  if (!bruto) return "";
  const digitos = String(bruto).replace(/\D/g, "");
  if (digitos === "") return "";
  if (digitos.indexOf("55") === 0) return digitos;
  if (digitos.length === 10 || digitos.length === 11) return "55" + digitos;
  return digitos;
}
function telefoneValido(normalizado) {
  if (!/^55[1-9][1-9]\d{8,9}$/.test(normalizado)) return false;
  return normalizado.length === 12 || normalizado.charAt(4) === "9";
}
function emailValido(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function primeiroNome(nome) {
  const partes = String(nome).trim().split(/\s+/);
  const p = partes[0] || "";
  return p.charAt(0).toUpperCase() + p.substring(1).toLowerCase();
}

// ---------- 1) Vendedores do cadastro (contato) ----------
const cadastro = {};
const cadastroPorNome = {};
pegarRegistros($node["Vendedores"].json).forEach(function (v) {
  const chave = chaveCodigo(v.codigo);
  if (chave === "") return;
  let telefone = "";
  const candidatos = [v.celular, v.telefone, v.fone, v.whatsapp, v.phone];
  for (let i = 0; i < candidatos.length && telefone === ""; i++) {
    const n = normalizarTelefone(candidatos[i]);
    if (telefoneValido(n)) telefone = n;
  }
  const email = String(v.email || "").trim();
  let telefoneBruto = "";
  for (let i = 0; i < candidatos.length && telefoneBruto === ""; i++) {
    if (candidatos[i] !== undefined && candidatos[i] !== null && String(candidatos[i]).trim() !== "") telefoneBruto = String(candidatos[i]).trim();
  }
  cadastro[chave] = {
    nome: decodificarEntidadesHtml(v.nome),
    telefone: telefone,
    email: emailValido(email) ? email : "",
    telefoneBruto: telefoneBruto,
    emailBruto: email
  };
  const nomeNorm = normalizarChave(decodificarEntidadesHtml(v.nome));
  if (nomeNorm !== "") cadastroPorNome[nomeNorm] = cadastro[chave];
});

// ---------- 2) Um registro por cliente (soma compras, vale a data mais recente) ----------
const registros = pegarRegistros($node["Clientes"].json);
if (registros.length === 0) {
  throw new Error("O relatório do Data Lab não retornou clientes. Confira o ID do relatório no node Clientes.");
}
const ignorados = {};
CONFIG.nomesIgnorados.forEach(function (n) { ignorados[n.toUpperCase()] = true; });

const clientes = {};
for (let i = 0; i < registros.length; i++) {
  const reg = registros[i];
  const nome = decodificarEntidadesHtml(pegarCampo(reg, "cliente")).trim();
  if (nome === "" || ignorados[nome.toUpperCase()]) continue;
  const dia = diaDaData(pegarCampo(reg, "ultimaCompra"));
  if (dia === null) continue;
  const chave = chaveCodigo(pegarCampo(reg, "codigo")) || nome.toUpperCase();
  const qtdBruta = pegarCampo(reg, "qtd");
  const qtd = (qtdBruta === "") ? 1 : (Number(qtdBruta) || 0);
  const atual = clientes[chave];
  if (!atual) {
    clientes[chave] = { nome: nome, dia: dia, qtd: qtd, reg: reg };
  } else {
    atual.qtd += qtd;
    if (dia > atual.dia) { atual.dia = dia; atual.reg = reg; }
  }
}

// ---------- 3) Radar: cliente novo (1 compra) com X dias ou mais sem comprar, por vendedor ----------
const hojeTexto = String($today);
const hojeDia = diaDaData(hojeTexto);
const grupos = {};
let totalClientes = 0;
Object.keys(clientes).forEach(function (chave) {
  const c = clientes[chave];
  const dias = hojeDia - c.dia;
  if (c.qtd !== CONFIG.qtdComprasNovo) return;
  if (dias < CONFIG.diasRadar) return;
  if (CONFIG.diasMaximoRadar > 0 && dias > CONFIG.diasMaximoRadar) return;
  const nomeVendRel = decodificarEntidadesHtml(pegarCampo(c.reg, "vendedor")).trim();
  const chaveVend = chaveCodigo(pegarCampo(c.reg, "vendedorCodigo")) || (nomeVendRel !== "" ? "NOME:" + nomeVendRel.toUpperCase() : "SEM_VENDEDOR");
  if (!grupos[chaveVend]) grupos[chaveVend] = { nomeRelatorio: nomeVendRel, lista: [] };
  const fone = String(pegarCampo(c.reg, "fone")).trim();
  const celular = String(pegarCampo(c.reg, "celular")).trim();
  const telefones = [];
  [celular, fone].forEach(function (t) { if (t !== "" && telefones.indexOf(t) < 0) telefones.push(t); });
  grupos[chaveVend].lista.push({
    nome: c.nome,
    dias: dias,
    ultimaCompra: formatarDataBr(pegarCampo(c.reg, "ultimaCompra")),
    telefone: telefones.join(" / "),
    email: String(pegarCampo(c.reg, "email")).trim()
  });
  totalClientes++;
});

// ---------- 4) Uma lista por vendedor (do cliente mais recente no radar para o mais antigo) ----------
const vendedores = [];
const semContato = [];
Object.keys(grupos).forEach(function (chaveVend) {
  const g = grupos[chaveVend];
  const cad = cadastro[chaveVend] || cadastroPorNome[normalizarChave(g.nomeRelatorio)];
  const nome = (cad && cad.nome) ? cad.nome : (g.nomeRelatorio || CONFIG.nomeSemVendedor);
  const telefone = cad ? cad.telefone : "";
  const email = cad ? cad.email : "";
  if (telefone === "" && email === "") {
    let motivo = "";
    if (chaveVend === "SEM_VENDEDOR") {
      motivo = "clientes sem vendedor definido no cadastro do cliente";
    } else if (!cad) {
      motivo = "vendedor não encontrado no cadastro";
    } else {
      const motivoTel = cad.telefoneBruto === "" ? "sem telefone cadastrado" : "telefone inválido: " + cad.telefoneBruto;
      const motivoMail = cad.emailBruto === "" ? "sem e-mail cadastrado" : "e-mail inválido: " + cad.emailBruto;
      motivo = motivoTel + "; " + motivoMail;
    }
    semContato.push({
      nome: nome,
      codigo: chaveVend,
      quantidade: g.lista.length,
      motivo: motivo,
      clientes: g.lista.slice().sort(function (a, b) { return a.dias - b.dias; }).map(function (c) {
        return { "Cliente": c.nome, "Telefone": c.telefone, "E-mail": c.email, "Primeira compra": c.ultimaCompra, "Dias sem comprar": c.dias };
      })
    });
  }
  const lista = g.lista.sort(function (a, b) { return a.dias - b.dias; });
  vendedores.push({
    codigo: chaveVend,
    nome: nome,
    telefone: telefone,
    email: email,
    quantidade: lista.length,
    clientes: lista.map(function (c) {
      return { "Cliente": c.nome, "Telefone": c.telefone, "E-mail": c.email, "Primeira compra": c.ultimaCompra, "Dias sem comprar": c.dias };
    })
  });
});
vendedores.sort(function (a, b) {
  if (b.quantidade !== a.quantidade) return b.quantidade - a.quantidade;
  return a.nome < b.nome ? -1 : 1;
});
vendedores.forEach(function (v, i) { v.posicao = i + 1; });

console.log("Clientes lidos: " + registros.length + " | clientes distintos: " + Object.keys(clientes).length + " | no radar: " + totalClientes + " | vendedores: " + vendedores.length);
console.log("Grupos de vendedor: " + vendedores.map(function (v) { return v.nome + " [" + v.codigo + "] = " + v.quantidade + (v.telefone || v.email ? "" : " (sem contato)"); }).join(" | "));
if (semContato.length > 0) console.log("Vendedores sem telefone nem e-mail válido (não recebem): " + semContato.map(function (s) { return s.nome + " (" + s.motivo + ")"; }).join(", "));

return [{ json: {
  total: totalClientes,
  totalVendedores: vendedores.length,
  diasRadar: CONFIG.diasRadar,
  diasMaximoRadar: CONFIG.diasMaximoRadar,
  data: formatarDataBr(hojeTexto),
  dataTitulo: formatarDataBr(hojeTexto).replace(/\//g, "-"),
  aba: CONFIG.nomeAba,
  semContato: semContato,
  vendedores: vendedores
} }];

// ================== CONFIG ==================
var COLUNA_VENDEDOR = "Vendedor";
var COLUNA_CLIENTES = "Clientes";
var COLUNA_LINK = "Link";
// ============================================

var vendedor = $node["Cada Vendedor"].json;
var planilha = $node["Criar Planilha do Vendedor"].json;

var linha = {};
linha[COLUNA_VENDEDOR] = vendedor.nome;
linha[COLUNA_CLIENTES] = vendedor.quantidade;
linha[COLUNA_LINK] = planilha.spreadsheetUrl;

return [{ json: linha }];

// ============================================================
// CONFIG - único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  limiteClientesWhatsapp: 10,    // quantos clientes aparecem no texto do WhatsApp (a planilha tem todos)
  limiteClientesEmail: 500,      // teto de linhas da tabela do e-mail
  tamanhoMaximoNome: 32,         // corta nomes longos no WhatsApp
  nomeEmpresa: "NOME DA EMPRESA",
  contatoDuvidasNome: "Nome do Responsável",
  contatoDuvidasWhatsapp: "(00) 00000-0000"
};

// ============================================================
// PADRÃO DE E-MAIL WAIPE - copie este bloco para o node `code` que monta o e-mail.
// Desenho de referência: o consolidado do gestor do Guardião da Amostra Padrão (claro, com modo escuro automático).
// Marca "waipe" e empresa no topo, cartão branco com faixa escura, título com eyebrow dourado, indicadores
// em verde-oliva, tabelas claras e rodapé Londrisoft. Todo e-mail de agente do Waipe usa este kit.
// As funções devolvem linhas de tabela (<tr>) para dentro do cartão, exceto wpBadge/wpBarra/wpSeta, que devolvem
// HTML para colocar dentro de uma célula. wpPagina devolve o documento HTML completo.
// Compatível com o sandbox do Waipe Flow (sem toLocaleString, sem Intl).
// ============================================================
const WP_F = "font-family:Arial,Helvetica,sans-serif;";

function wpEsc(t) {
  if (t === null || t === undefined) return "";
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}
function wpNum(n) { return String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
function wpMoeda(v) {
  const n = Math.round((Number(v) || 0) * 100) / 100;
  const p = Math.abs(n).toFixed(2).split(".");
  return (n < 0 ? "-R$ " : "R$ ") + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + p[1];
}

// Estilos de destaque (badge, KPI e aviso): fundo, texto e borda. As cores do modo escuro ficam no <style> de wpPagina.
const WP_ESTILOS = {
  neutro: { bg: "#F9FAFB", cor: "#303030", borda: "#E5E7EB" },
  medio: { bg: "#F1F2EC", cor: "#5A6344", borda: "#E3E6D8" },
  forte: { bg: "#5A6344", cor: "#FFFFFF", borda: "#5A6344" },
  alerta: { bg: "#FEF3F2", cor: "#B42318", borda: "#FAD7D3" },
  ok: { bg: "#EEF8F1", cor: "#1E7A45", borda: "#CDEBD7" }
};

// Documento completo: marca e empresa, cartão (eyebrow, título, saudação, destaque), miolo (linhas) e rodapé.
// o: { preheader, empresa, rotuloDireita, eyebrow, titulo, heroEyebrow, heroValor, heroTam, heroSub, heroBarra,
//      heroNota, saudacao, subSaudacao, miolo, rodape: [linhas] }
// eyebrow/titulo são opcionais: sem eles, heroEyebrow vira o eyebrow do cartão.
function wpPagina(o) {
  const eyebrow = o.eyebrow || o.heroEyebrow || "";
  let h = "";
  h += "<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>";
  h += "<meta name='color-scheme' content='light dark'><meta name='supported-color-schemes' content='light dark'>";
  h += "<title>" + wpEsc(o.titulo || eyebrow || o.empresa || "Waipe") + "</title>";
  h += "<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;}a{color:#303030;}";
  h += "@media only screen and (max-width:620px){.wp-wrap{width:100%!important;max-width:100%!important;}.wp-pad{padding-left:16px!important;padding-right:16px!important;}.wp-kpi{display:block!important;width:100%!important;padding:0 0 8px 0!important;}.wp-hide{display:none!important;}.wp-h1{font-size:24px!important;line-height:30px!important;}.wp-hero{font-size:40px!important;line-height:44px!important;}}";
  h += "@media (prefers-color-scheme: dark){.wp-bg{background:#16181D!important;}.wp-card{background:#1F2229!important;border-color:#323743!important;}.wp-soft{background:#272B33!important;}.wp-t{color:#F3F4F6!important;}.wp-m{color:#A8AEBB!important;}.wp-bd{border-color:#323743!important;}.wp-eb{color:#D4B25A!important;}";
  h += "td[bgcolor='#303030']{background:#E5E7EB!important;}td[bgcolor='#303030'] a{color:#1F2229!important;}";
  h += "td[bgcolor='#F9FAFB']{background:#272B33!important;}td[bgcolor='#F1F2EC']{background:#2A2E24!important;}td[bgcolor='#E3E6D8']{background:#3A4030!important;}";
  h += "td[bgcolor='#FEF3F2']{background:#3A2422!important;}td[bgcolor='#EEF8F1']{background:#1F3A2C!important;}td[bgcolor='#F3F4F6']{background:#272B33!important;}";
  h += ".wp-c-medio{color:#C9CFB4!important;}.wp-c-neutro{color:#F3F4F6!important;}.wp-c-alerta{color:#FCA5A5!important;}.wp-c-ok{color:#86EFAC!important;}}";
  h += "</style></head>";
  h += "<body class='wp-bg' style='margin:0;padding:0;background:#F3F4F6;'>";
  h += "<span style='display:none;font-size:1px;color:#F3F4F6;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;'>" + wpEsc(o.preheader || "") + "</span>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' bgcolor='#F3F4F6' class='wp-bg' style='background:#F3F4F6;'><tr><td align='center' style='padding:32px 12px;'>";
  h += "<!--[if mso]><table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0'><tr><td><![endif]-->";
  h += "<table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0' class='wp-wrap' style='width:600px;max-width:600px;'>";
  // Marca
  h += "<tr><td class='wp-pad' style='padding:0 8px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  h += "<td class='wp-t' style='" + WP_F + "font-size:22px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:28px;'>waipe</td>";
  h += "<td align='right' class='wp-m' style='" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(o.empresa || "") + (o.rotuloDireita ? "<br>" + o.rotuloDireita : "") + "</td>";
  h += "</tr></table></td></tr>";
  // Cartão
  h += "<tr><td bgcolor='#FEFEFE' class='wp-card' style='background:#FEFEFE;border:1px solid #E5E7EB;border-radius:12px;overflow:hidden;'>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>";
  h += "<tr><td height='4' bgcolor='#303030' style='height:4px;font-size:0;line-height:0;background:#303030;border-radius:12px 12px 0 0;'>&nbsp;</td></tr>";
  if (eyebrow || o.titulo || o.saudacao) {
    h += "<tr><td class='wp-pad' style='padding:32px 32px 8px 32px;'>";
    if (eyebrow) h += "<p class='wp-eb' style='margin:0 0 8px 0;" + WP_F + "font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#8E6A1F;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(eyebrow) + "</p>";
    if (o.titulo) h += "<h1 class='wp-h1 wp-t' style='margin:0 0 12px 0;" + WP_F + "font-size:28px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:34px;'>" + wpEsc(o.titulo) + "</h1>";
    if (o.saudacao) h += "<p class='wp-t' style='margin:0;" + WP_F + "font-size:15px;color:#303030;mso-line-height-rule:exactly;line-height:23px;'>" + o.saudacao + "</p>";
    if (o.subSaudacao) h += "<p class='wp-m' style='margin:6px 0 0 0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + o.subSaudacao + "</p>";
    h += "</td></tr>";
  }
  if (o.heroValor !== undefined && o.heroValor !== null) {
    const tam = Math.min(o.heroTam || 44, 48);
    h += "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='#F1F2EC' style='background:#F1F2EC;border-radius:8px;padding:20px;'>";
    if (o.heroEyebrow && o.eyebrow && o.eyebrow !== o.heroEyebrow) h += "<p class='wp-c-medio' style='margin:0 0 6px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#5A6344;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(o.heroEyebrow) + "</p>";
    h += "<p class='wp-hero wp-c-medio' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:#5A6344;letter-spacing:-1px;mso-line-height-rule:exactly;line-height:" + (tam + 4) + "px;'>" + wpEsc(o.heroValor) + "</p>";
    if (o.heroSub) h += "<p class='wp-c-medio' style='margin:6px 0 0 0;" + WP_F + "font-size:14px;color:#5A6344;mso-line-height-rule:exactly;line-height:20px;'>" + o.heroSub + "</p>";
    if (o.heroBarra !== undefined && o.heroBarra !== null) {
      const w = Math.max(0, Math.min(100, Math.round(o.heroBarra)));
      h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:14px;'><tr><td bgcolor='#E3E6D8' style='background:#E3E6D8;border-radius:5px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>" +
        "<td width='" + w + "%' height='10' bgcolor='#5A6344' style='height:10px;background:#5A6344;border-radius:5px;font-size:0;line-height:0;'>&nbsp;</td>" +
        (w < 100 ? "<td height='10' style='height:10px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table></td></tr></table>";
    }
    if (o.heroNota) h += "<p class='wp-c-medio' style='margin:10px 0 0 0;" + WP_F + "font-size:12px;color:#5A6344;mso-line-height-rule:exactly;line-height:18px;'>" + o.heroNota + "</p>";
    h += "</td></tr></table></td></tr>";
  }
  h += o.miolo || "";
  h += "<tr><td style='height:24px;font-size:0;line-height:0;'>&nbsp;</td></tr>";
  h += "</table></td></tr>";
  // Rodapé
  const linhasRodape = o.rodape || [];
  h += "<tr><td class='wp-pad' align='center' style='padding:24px 24px 0 24px;'>";
  for (let i = 0; i < linhasRodape.length; i++) {
    h += "<p class='wp-m' style='margin:" + (i > 0 ? "6px" : "0") + " 0 0 0;" + WP_F + "font-size:12px;color:" + (i === linhasRodape.length - 1 ? "#8A90A0" : "#6B7280") + ";mso-line-height-rule:exactly;line-height:18px;'>" + linhasRodape[i] + "</p>";
  }
  h += "</td></tr></table>";
  h += "<!--[if mso]></td></tr></table><![endif]-->";
  h += "</td></tr></table></body></html>";
  return h;
}

// Parágrafo livre (HTML já escapado pelo chamador)
