const RODAPE2 = "Se tiver alguma dúvida, fale com o " + CONFIG.contatoDuvidasNome + " pelo WhatsApp " + CONFIG.contatoDuvidasWhatsapp + ".";
const F = "font-family:Arial, Helvetica, sans-serif;";
const exibidos = Math.min(qtd, CONFIG.limiteClientesWhatsapp);
const faixaCurta = dados.diasMaximoRadar > 0 ? ("de " + dados.diasRadar + " a " + dados.diasMaximoRadar + " dias sem comprar") : (dados.diasRadar + " dias ou mais sem comprar");
const faixaTexto = dados.diasMaximoRadar > 0 ? ("entre " + dados.diasRadar + " e " + dados.diasMaximoRadar + " dias") : (dados.diasRadar + " dias ou mais");

// ---------- WhatsApp: os mais recentes no radar primeiro (20 dias, 21, 22...), e o link da planilha completa ----------
let zap = "Olá, " + primeiroNome(v.nome) + "! Tenha um ótimo dia.\n";
