zap += "⏰ No radar: " + faixaCurta + "\n";
zap += DIVISOR + "\n";
zap += (exibidos === 1) ? "🔔 O cliente no radar:\n" : "🔔 Os " + exibidos + " mais recentes (do mais perto dos " + dados.diasRadar + " dias ao mais antigo):\n";
clientes.slice(0, exibidos).forEach(function (c, i) {
  zap += (i + 1) + ". *" + cortar(c["Cliente"], CONFIG.tamanhoMaximoNome) + "*\n";
  zap += "⏳ " + c["Dias sem comprar"] + " dias (1ª compra em " + c["Primeira compra"] + ")\n";
