});
if (qtd > exibidos) zap += "➕ ...e mais " + (qtd - exibidos) + ((qtd - exibidos) === 1 ? " cliente.\n" : " clientes.\n");
if (urlPlanilha !== "") zap += "📊 Planilha completa com todos os clientes:\n" + urlPlanilha + "\n";
zap += DIVISOR + "\n_" + RODAPE1 + "_\n_" + RODAPE2 + "_";

// ---------- E-mail: padrão Waipe (tabela completa + botão para a planilha) ----------
const plural = qtd === 1 ? "cliente novo está" : "clientes novos estão";
const linhasEmail = clientes.slice(0, CONFIG.limiteClientesEmail).map(function (c) {
