const dados = $node["Processar Radar"].json;

// Link da planilha de cada vendedor: vem da planilha-índice (node Ler Índice), preenchida durante o loop
const links = {};
const valoresIndice = (items.length > 0 && items[0].json && Array.isArray(items[0].json.values)) ? items[0].json.values : [];
if (valoresIndice.length > 1) {
  const cab = valoresIndice[0].map(function (x) { return String(x).trim().toLowerCase(); });
  const iNome = cab.indexOf("vendedor");
  const iLink = cab.indexOf("link");
  for (let r = 1; r < valoresIndice.length; r++) {
    const linha = valoresIndice[r];
    if (iNome >= 0 && iLink >= 0 && linha[iNome] && linha[iLink]) links[String(linha[iNome])] = String(linha[iLink]);
  }
}
console.log("Links de planilha lidos do índice: " + Object.keys(links).length + " de " + dados.vendedores.length);

const vendedores = dados.vendedores;
const maximo = vendedores.length > 0 ? vendedores[0].quantidade : 1;
const faixa = dados.diasMaximoRadar > 0 ? "entre " + dados.diasRadar + " e " + dados.diasMaximoRadar + " dias" : dados.diasRadar + " dias ou mais";
const linhas = vendedores.map(function (v, i) {
  const url = links[v.nome] || "";
  return [
    wpBadge(String(v.posicao), i < 3 ? "forte" : "neutro"),
    "<b>" + wpEsc(v.nome) + "</b>" + wpBarra(v.quantidade / maximo * 100, i < 3),
    "<b>" + wpNum(v.quantidade) + "</b>",
    url ? wpSeta(url, "Abrir a planilha de " + v.nome) : "-"
  ];
});

// Vendedores que não receberam o radar (sem telefone nem e-mail válido), com os clientes de cada um
let pendencias = "";
const semContato = Array.isArray(dados.semContato) ? dados.semContato : [];
if (semContato.length > 0) {
  let corpo = "Sem telefone nem e-mail válido no cadastro. Corrija o cadastro para o próximo envio chegar. A planilha deles foi criada normalmente.";
  semContato.forEach(function (s) {
    corpo += '<span style="display:block;padding-top:12px;"><strong style="color:#303030;">' + wpEsc(s.nome) + ' (' + wpNum(s.quantidade) + ')</strong> <span style="color:#6B7280;">' + wpEsc(s.motivo) + '</span></span>';
    (Array.isArray(s.clientes) ? s.clientes : []).slice(0, CONFIG.maxClientesPorPendencia).forEach(function (c) {
      corpo += '<span style="display:block;padding-left:10px;color:#5B6170;">&bull; ' + wpEsc(c["Cliente"]) + ' &middot; ' + wpNum(c["Dias sem comprar"]) + ' dias' + (c["Telefone"] ? ' &middot; ' + wpEsc(c["Telefone"]) : '') + '</span>';
    });
  });
  pendencias = wpAviso("Vendedores que não receberam o radar", corpo, "medio");
}

const miolo =
  wpKpis([
    { rotulo: "Vendedores com radar", valor: wpNum(vendedores.length) },
    { rotulo: "Maior radar", valor: vendedores.length > 0 ? wpNum(vendedores[0].quantidade) : "0", sub: vendedores.length > 0 ? vendedores[0].nome : "" }
  ]) +
  wpSecao("Ranking por vendedor", "Do maior para o menor. Clique na seta para abrir a planilha completa.") +
  wpTabela([{ t: "#", w: "44" }, { t: "Vendedor" }, { t: "Clientes", a: "right", w: "70" }, { t: "Lista", a: "right", w: "60" }], linhas) +
  pendencias;

